def merge_dedup(seq1, seq2):
    """Merge two sorted lists, removing duplicates."""
    result = []
    i = j = 0
    while i < len(seq1) and j < len(seq2):
        if seq1[i] < seq2[j]:
            if not result or result[-1] != seq1[i]:
                result.append(seq1[i])
            i += 1
        else:
            if not result or result[-1] != seq2[j]:
                result.append(seq2[j])
            j += 1
    result.extend(seq1[i:])
    result.extend(seq2[j:])
    return result

def merge_dedup(seq1: list[int], seq2: list[int]) -> list[int]:
    """Merge two sorted lists into one sorted list without duplicates.
    Args: seq1: first sorted list; seq2: second sorted list
    Returns: Merged and deduplicated sorted list
    """
    result: list[int] = []
    i = j = 0
    while i < len(seq1) and j < len(seq2):
        if seq1[i] < seq2[j]:
            if not result or result[-1] != seq1[i]:
                result.append(seq1[i])
            i += 1
        else:
            if not result or result[-1] != seq2[j]:
                result.append(seq2[j])
            j += 1
    result.extend(seq1[i:])
    result.extend(seq2[j:])
    return result
